/**
 * The ready-made pages, by key. Every page mounts at its default path; give a
 * key a path to mount the page there instead, or `false` to turn it off. An
 * app page at a page's path always wins: the module detects it and mounts
 * nothing there.
 */
export interface ModulePagesOptions {
  /** Where an invited person accepts a workspace invitation (private). Default `/accept-invitation`; the module writes it into the functions directory's `paths.generated.ts`, which invitation emails link from. */
  acceptInvitation?: string | false
  /** The accessibility statement (public): the standard the app follows, how it is checked, and where to report a barrier, filled from `appConfig.backend.legal` and marked "not legal advice". Default `/legal/accessibility`. */
  accessibility?: string | false
  /** The admin console: accounts, workspaces, the activity trail and the app's health (private and hidden: it answers 404 to anyone without the `admin` role). Default `/admin`. */
  admin?: string | false
  /** The gifts a person sent and received, with resend, change, cancel and claim (private). Default `/gifts`. */
  gifts?: string | false
  /** Where an access link lands (public, kept out of search indexes): it checks the link's token and sends the person on to sign in. Default `/invite`. */
  invite?: string | false
  /** Where the "keep my account" link of a scheduled deletion lands (public, kept out of search indexes). Default `/account/keep`; the module writes it into the functions directory's `paths.generated.ts`, which the deletion email links from. */
  keepAccount?: string | false
  /** The sign-in page (public, kept out of search indexes), and where the page guard sends a signed-out visitor. Default `/login`. */
  login?: string | false
  /** The pricing page (public). Default `/pricing`. */
  pricing?: string | false
  /** The privacy policy (public): who runs the app, the data map, the subprocessors, the cookies and how a person exports or deletes their data, filled from `appConfig.backend.legal` and the capabilities the app uses, and marked "not legal advice". Default `/legal/privacy`. */
  privacy?: string | false
  /** The account profile (private). Default `/profile`. */
  profile?: string | false
  /** Where a referral link lands (`/r/<code>`; public, kept out of search indexes): it says who invited the visitor and what they get, and signing up there claims the referral. Default `/r/:code`. */
  referral?: string | false
  /** The public notice form (DSA Art. 16, the TAKE IT DOWN Act's removal request), open to people without an account, and where a statement of reasons' appeal link lands (`#appeal=<token>`). Default `/report`. */
  report?: string | false
  /** Passkeys, sessions, account deletion and the account's recent activity (private). Default `/security`. */
  security?: string | false
  /** Workspace, plan and credit settings, and the workspace's activity for its owners and admins (private). Default `/settings`. */
  settings?: string | false
  /** The subprocessor list (public): each service that processes personal data for the capabilities the app uses, what it handles, where, and its agreement; marked "not legal advice". Default `/legal/subprocessors`. */
  subprocessors?: string | false
  /** The terms of service (public): the company and contact, accounts and sign-in, plans and renewal, the merchant of record's role and the content rules, filled from `appConfig.backend.legal` and the capabilities the app uses, and marked "not legal advice". Default `/legal/terms`. */
  terms?: string | false
  /** Where a topic email's unsubscribe link and a double opt-in's confirmation link land (public, kept out of search indexes and caches): one press leaves the topic, or confirms it. Default `/unsubscribe`. */
  unsubscribe?: string | false
  /** Where a waitlist status link lands (public, kept out of search indexes): a person's place in the line, read from the signed token in the link's fragment. Default `/waitlist`. */
  waitlist?: string | false
  /** The first run a new account sees once after its first sign-in: name, workspace, teammates and a plan, with steps of your own (private). Default `/welcome`. */
  welcome?: string | false
}
